button.clickEventHandler:

  if (data.requisites.find(re => re.name == "NeedActiveTextDirRX").value === false || 
      data.requisites.find(re => re.name == "NeedActiveTextDirRX").value === null)
  {
    var isAssignmentBlocked = ESS.network.sendRequest(`/api/functions/IsAssignmentCardBlocked?assignmentId=${data.id}`);
    isAssignmentBlocked.then(message => {
      if (!message) {
        ESS.actions.workProcessActions.changeWorkItemState(data, 'Complete', 'Complete').then(function () {
          ESS.closeElement(sender);
          ESS.toasts.showToast(ESS.L('@HRPROSTATEMENTS.OBJECTCARD_ASSIGNMENT_SUCCESSMESSAGE'), 'success', true);
          ESS.widgets.updateWidgets();
        }).catch(function (error) {
          ESS.toasts.showErrorToastWithLog(ESS.L('@HRPROSTATEMENTS.ERR_ASSIGNMENT_COMPLETION_FAILURE'), error.message);
        });
      } else {
        ESS.toasts.showToast(message, 'danger', false);
      }
    });
  }
  else {
    ESS.actions.facilityActions.runFacility({id: 'cbf8e1d7-d66c-4451-ac22-14865f87e8d8'}, {parameters: {ItemId: data.id, ItemName: data.name}}, sender);
  }


  var isAssignmentBlocked = ESS.network.sendRequest(`/api/functions/IsAssignmentCardBlocked?assignmentId=${data.id}`);
  isAssignmentBlocked.then(message => {
    if (!message) {
      ESS.actions.workProcessActions.changeWorkItemState(data, 'Complete', 'Noted').then(function () {
        ESS.closeElement(sender);
        ESS.toasts.showToast(ESS.L('@HRPROSTATEMENTS.OBJECTCARD_ASSIGNMENT_SUCCESSMESSAGE'), 'success', true);
        ESS.widgets.updateWidgets();
      }).catch(function (error) {
        ESS.toasts.showErrorToastWithLog(ESS.L('@HRPROSTATEMENTS.ERR_ASSIGNMENT_COMPLETION_FAILURE'), error.message);
      });
    } else {
      ESS.toasts.showToast(message, 'danger', false);
    }
  });


  var attachmentTitle = data.attachments.filter(function(attachment) {
    return attachment.group === "DocumentGroup";
  });
  var docName = "";
  attachmentTitle.forEach(attachment => {
    if (docName === "")
      docName = attachment.title
    else
      docName = docName + "; " + attachment.title
  })
  ESS.actions.facilityActions.runFacility({id: 'd3f7270a-2680-44fe-b231-1708b532beb3'}, {parameters: {ItemId: data.id, ItemName: data.name, DocName: docName, StateName: 'ForRevision', IsSigned: false}}, sender);


  var isAssignmentBlocked = ESS.network.sendRequest(`/api/functions/IsAssignmentCardBlocked?assignmentId=${data.id}`);
  isAssignmentBlocked.then(message => {
    if (!message) {
      ESS.actions.workProcessActions.changeWorkItemState(data, 'Complete', 'Approved').then(function () {
        ESS.closeElement(sender);
        ESS.toasts.showToast(ESS.L('Документы согласованы.'), 'success', true);
        ESS.widgets.updateWidgets();
      }).catch(function (error) {
        ESS.toasts.showErrorToastWithLog(ESS.L('При выполнении задания произошла ошибка. Обратитесь к администратору.'), error.message);
      });
    } else {
      ESS.toasts.showToast(message, 'danger', false);
    }
  });


  var attachmentTitle = data.attachments.filter(function(attachment) {
    return attachment.group === "DocumentGroup";
  });
  var docName = "";
  attachmentTitle.forEach(attachment => {
    if (docName === "")
      docName = attachment.title
    else
      docName = docName + "; " + attachment.title
  })
  ESS.actions.facilityActions.runFacility({id: 'b908bc4a-5c80-4841-af63-942250079765'}, {parameters: {ItemId: data.id, ItemName: data.name, DocName: docName}}, sender);


  var attachmentTitle = data.attachments.filter(function(attachment) {
    return attachment.group === "DocumentGroup";
  });
  var docName = "";
  attachmentTitle.forEach(attachment => {
    if (docName === "")
      docName = attachment.title
    else
      docName = docName + "; " + attachment.title
  })
  ESS.actions.facilityActions.runFacility({id: 'C910C78C-A9F1-4DA6-AB15-BE36D4BAB354'}, {parameters: {ItemId: data.id, ItemName: data.name, DocName: docName}}, sender);

objectCard.openedEventHandler:
      
        ESS.network.sendRequest(`/api/functions/GetTaskActiveText?assignmentId=${data.id}`)
        .then(function (activeText){
          data.comment = activeText.replace(/([\r\n])/g, '<br/>');
          resolve({configuration: configuration, data: data});
        })
        .catch(function (error) {
          ESS.toasts.showToast(error.message, 'danger', false);
          reject();
        });

        if(data.requisites.find(re => re.name == "CanComplete").value === false || 
           data.requisites.find(re => re.name == "CanComplete").value === null)
        {
          configuration.buttons.splice(configuration.buttons.findIndex(bu => bu.name === "Complete"), 1);
        }
        if(data.requisites.find(re => re.name == "CanForRevision").value === false || 
           data.requisites.find(re => re.name == "CanForRevision").value === null)
        {
          configuration.buttons.splice(configuration.buttons.findIndex(bu => bu.name === "Revision"), 1);
        }
        if(data.requisites.find(re => re.name == "CanApprove").value === false || 
           data.requisites.find(re => re.name == "CanApprove").value === null)
        {
          configuration.buttons.splice(configuration.buttons.findIndex(bu => bu.name === "Approve"), 1);
        }
        if(data.requisites.find(re => re.name == "CanRefuse").value === false || 
           data.requisites.find(re => re.name == "CanRefuse").value === null)
        {
          configuration.buttons.splice(configuration.buttons.findIndex(bu => bu.name === "Refuse"), 1);
        }
        if(data.requisites.find(re => re.name == "CanTerminate").value === false || 
           data.requisites.find(re => re.name == "CanTerminate").value === null)
        {
          configuration.buttons.splice(configuration.buttons.findIndex(bu => bu.name === "Terminate"), 1);
        }
        if(data.requisites.find(re => re.name == "CanNotedDirRX").value === false || 
           data.requisites.find(re => re.name == "CanNotedDirRX").value === null)
        {
          configuration.buttons.splice(configuration.buttons.findIndex(bu => bu.name === "Noted"), 1);
        }
